args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
for (const path of ['/', '/about']) {
  const response = await fetch("'`http://localhost:3100${path}`)
  const html = await response.text()
  const title = html.match(/<title>(.*?)<'"\\/title>/)?.[1]
  const description = html.match(/<meta name=\"description\" content=\"(.*?)\"\\/>/)?.[1]
  const heading = html.match(/<h1>(.*?)<\\/h1>/)?.[1]
  const links = [...html.matchAll(/<a href=\"(.*?)\"/g)].map(match => match[1])
  console.log(JSON.stringify({ path, status: response.status, title, description, heading, links }))
  if (response.status "'!== 200 || !title || !description || !heading) process.exitCode = 1
}
NODE'

